import { mkdirSync, writeFileSync, readFileSync, existsSync, rmSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { findCapsuleAppBundle, copyDirRecursive } from './bundle-utils.js';
import { backendOrchestratorSource } from './backend-orchestrator-source.js';

/**
 * every test here spawns real child processes, so a failure in CI can hang the
 * whole file instead of failing one case. vitest only prints a file's results
 * once the file finishes, so an aborted run names nothing. tracing start/end to
 * stderr means the last "-> " line in the CI log is always the culprit.
 */
let testStartedAt = 0;
beforeEach((ctx: any) => {
  testStartedAt = Date.now();
  process.stderr.write(`-> ${ctx.task?.name}\n`);
});
afterEach((ctx: any) => process.stderr.write(`<- ${ctx.task?.name} (${Date.now() - testStartedAt}ms)\n`));

/** ceiling for any single test that spawns a child; must stay under the 15s watchdog. */
const CHILD_TEST_TIMEOUT = 10000;

function makeTmpDir(prefix: string): string {
  const dir = join(tmpdir(), `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
  mkdirSync(dir, { recursive: true });
  return dir;
}

function writeCapsuleArtifact(rootDir: string, capsuleName: string, artifactPath: string, content: string) {
  const fullPath = join(rootDir, capsuleName, 'artifacts', 'app-bundle', artifactPath);
  mkdirSync(join(fullPath, '..'), { recursive: true });
  writeFileSync(fullPath, content);
}

const fakeId = (name: string) => ({ toStringWithoutVersion: () => name });

describe('findCapsuleAppBundle', () => {
  it('finds app-bundle via graphCapsules when component is in same env', () => {
    const rootDir = makeTmpDir('capsule-same-env');
    const capsulePath = join(rootDir, 'my.scope_my-service@abc123');
    mkdirSync(join(capsulePath, 'artifacts', 'app-bundle'), { recursive: true });
    writeFileSync(join(capsulePath, 'artifacts', 'app-bundle', 'my-service.cjs'), 'module.exports = {}');

    const capsuleNetwork = {
      capsulesRootDir: rootDir,
      graphCapsules: {
        getCapsuleIgnoreVersion: (id: any) => {
          if (id.toStringWithoutVersion() === 'my.scope/my-service') {
            return { path: capsulePath };
          }
          return undefined;
        },
      },
    };

    const result = findCapsuleAppBundle(capsuleNetwork, fakeId('my.scope/my-service'));
    expect(result).toBe(join(capsulePath, 'artifacts', 'app-bundle'));

    rmSync(rootDir, { recursive: true });
  });

  it('finds app-bundle via capsulesRootDir scan when component is in different env', () => {
    const rootDir = makeTmpDir('capsule-cross-env');
    writeCapsuleArtifact(rootDir, 'my.scope_examples_my-frontend@def456', 'index.html', '<html></html>');

    const capsuleNetwork = {
      capsulesRootDir: rootDir,
      graphCapsules: {
        getCapsuleIgnoreVersion: () => undefined,
      },
    };

    const result = findCapsuleAppBundle(capsuleNetwork, fakeId('my.scope/examples/my-frontend'));
    expect(result).toBe(join(rootDir, 'my.scope_examples_my-frontend@def456', 'artifacts', 'app-bundle'));

    rmSync(rootDir, { recursive: true });
  });

  it('returns undefined when no app-bundle exists on disk', () => {
    const rootDir = makeTmpDir('capsule-no-bundle');
    mkdirSync(join(rootDir, 'my.scope_my-service@abc123', 'artifacts'), { recursive: true });

    const capsuleNetwork = {
      capsulesRootDir: rootDir,
      graphCapsules: { getCapsuleIgnoreVersion: () => undefined },
    };

    const result = findCapsuleAppBundle(capsuleNetwork, fakeId('my.scope/my-service'));
    expect(result).toBeUndefined();

    rmSync(rootDir, { recursive: true });
  });

  it('returns undefined when capsuleNetwork is undefined', () => {
    const result = findCapsuleAppBundle(undefined, fakeId('my.scope/my-service'));
    expect(result).toBeUndefined();
  });
});

describe('copyDirRecursive', () => {
  it('copies files preserving directory structure and detects .cjs entry', () => {
    const srcDir = makeTmpDir('copy-src');
    const destDir = makeTmpDir('copy-dest');

    writeFileSync(join(srcDir, 'my-service.cjs'), 'module.exports = {}');
    writeFileSync(join(srcDir, 'my-service.cjs.map'), '{}');
    mkdirSync(join(srcDir, 'sub'));
    writeFileSync(join(srcDir, 'sub', 'helper.js'), 'exports.help = true');

    const result = copyDirRecursive(srcDir, destDir);

    expect(result.entry).toBe('my-service.cjs');
    expect(existsSync(join(destDir, 'my-service.cjs'))).toBe(true);
    expect(existsSync(join(destDir, 'my-service.cjs.map'))).toBe(true);
    expect(existsSync(join(destDir, 'sub', 'helper.js'))).toBe(true);
    expect(readFileSync(join(destDir, 'sub', 'helper.js'), 'utf8')).toBe('exports.help = true');

    rmSync(srcDir, { recursive: true });
    rmSync(destDir, { recursive: true });
  });

  it('copies frontend assets without detecting a .cjs entry', () => {
    const srcDir = makeTmpDir('copy-frontend-src');
    const destDir = makeTmpDir('copy-frontend-dest');

    writeFileSync(join(srcDir, 'index.html'), '<html></html>');
    mkdirSync(join(srcDir, 'assets'));
    writeFileSync(join(srcDir, 'assets', 'index-abc123.js'), 'console.log("app")');
    writeFileSync(join(srcDir, 'assets', 'index-abc123.css'), 'body{}');

    const result = copyDirRecursive(srcDir, destDir);

    expect(result.entry).toBeUndefined();
    expect(existsSync(join(destDir, 'index.html'))).toBe(true);
    expect(existsSync(join(destDir, 'assets', 'index-abc123.js'))).toBe(true);
    expect(existsSync(join(destDir, 'assets', 'index-abc123.css'))).toBe(true);

    rmSync(srcDir, { recursive: true });
    rmSync(destDir, { recursive: true });
  });

  it('ignores .cjs.map files for entry detection', () => {
    const srcDir = makeTmpDir('copy-map');
    const destDir = makeTmpDir('copy-map-dest');

    writeFileSync(join(srcDir, 'server.cjs.map'), '{}');

    const result = copyDirRecursive(srcDir, destDir);
    expect(result.entry).toBeUndefined();

    rmSync(srcDir, { recursive: true });
    rmSync(destDir, { recursive: true });
  });
});

