    const capsuleName = 'bitdev.platforms_examples_placeholder-frontend@6a533bfe3a64d24c880d1fc82b37a5b339b608ff';
    writeCapsuleArtifact(rootDir, capsuleName, 'index.html', '<html></html>');
    writeCapsuleArtifact(rootDir, capsuleName, 'assets/index-Bld2rk49.js', 'console.log("app")');

    const capsuleNetwork = {
      capsulesRootDir: rootDir,
      graphCapsules: { getCapsuleIgnoreVersion: () => undefined },
    };

    const result = findCapsuleAppBundle(capsuleNetwork, fakeId('bitdev.platforms/examples/placeholder-frontend'));
    expect(result).toBe(join(rootDir, capsuleName, 'artifacts', 'app-bundle'));

