describe('backend-orchestrator-source', () => {
  it('is valid JavaScript with expected CLI commands', () => {
    expect(typeof backendOrchestratorSource).toBe('string');
    expect(backendOrchestratorSource).toContain('manifest.json');
    expect(backendOrchestratorSource).toContain('--list');
    expect(backendOrchestratorSource).toContain('--help');
    expect(backendOrchestratorSource).toContain('--no-frontend');
  });
});

function setupOrchestratorBundle(manifest: object, services?: Record<string, string>): string {
  const dir = makeTmpDir('orchestrator');
  writeFileSync(join(dir, 'manifest.json'), JSON.stringify(manifest));
  writeFileSync(join(dir, 'backend.cjs'), backendOrchestratorSource);
  if (services) {
    for (const [path, content] of Object.entries(services)) {
      const full = join(dir, path);
      mkdirSync(join(full, '..'), { recursive: true });
      writeFileSync(full, content);
    }
  }
  mkdirSync(join(dir, 'frontend'), { recursive: true });
  writeFileSync(join(dir, 'frontend', 'index.html'), '<html><body>test</body></html>');
  return dir;
}

function minimalEnv(extra?: Record<string, string>): Record<string, string> {
  const base: Record<string, string> = { PATH: process.env.PATH || '' };
  if (process.env.HOME) base.HOME = process.env.HOME;
  if (process.env.NODE) base.NODE = process.env.NODE;
  return { ...base, ...extra };
}

/**
 * run the orchestrator and resolve on the child's *exit*, not on stdio EOF.
 *
 * execFile's callback waits for both the process to exit and its stdio to reach
 * EOF, and in a capsule container the latter never happens -- every call hung
 * until the per-test ceiling, even `--help`. exit is the event we actually care
 * about, so wait on that and treat stdio close as a best-effort flush.
 */
function runOrchestrator(dir: string, args: string[], env?: Record<string, string>): Promise<{ stdout: string; stderr: string; code: number | null }> {
  const { spawn } = require('child_process');
  return new Promise((resolve) => {
    const child = spawn(process.execPath, [join(dir, 'backend.cjs'), ...args], {
      env: minimalEnv(env),
      stdio: ['ignore', 'pipe', 'pipe'],
    });

    let stdout = '';
    let stderr = '';
    let code: number | null = null;
    const events: string[] = [];
    let settled = false;
    let flush: any;

    const finish = () => {
      if (settled) return;
      settled = true;
      clearTimeout(kill);
      clearTimeout(flush);
      // surfaces the child's lifecycle in CI logs, where this is otherwise opaque.
      process.stderr.write(`   [${args.join(' ') || 'default'}] ${events.join(',')}\n`);
      resolve({ stdout, stderr, code });
    };

    child.stdout.on('data', (c: any) => { stdout += c; });
    child.stderr.on('data', (c: any) => { stderr += c; });
    child.on('spawn', () => events.push('spawn'));
    child.on('error', (e: Error) => { events.push(`error:${e.message}`); code = 1; finish(); });
    child.on('close', () => { events.push('close'); finish(); });
    child.on('exit', (c: number | null, sig: string | null) => {
      events.push(`exit:${c ?? sig}`);
      code = c;
      // if stdio never reaches EOF, settle shortly after exit anyway.
      flush = setTimeout(finish, 300);
    });

    const kill = setTimeout(() => {
      events.push('timeout');
      child.kill('SIGKILL');
      setTimeout(finish, 200);
    }, 4000);
  });
}

describe('orchestrator --list', () => {
  it('lists gateway and services', async () => {
    const dir = setupOrchestratorBundle({
      name: 'test-platform',
      gateway: { name: 'gw', entry: 'gateway/gw.cjs' },
      frontend: { name: 'web', dir: 'frontend' },
      services: {
        'svc-a': { entry: 'services/svc-a/svc-a.cjs' },
        'svc-b': { entry: 'services/svc-b/svc-b.cjs' },
      },
    });

    const result = await runOrchestrator(dir, ['--list']);
    const lines = result.stdout.trim().split('\n');
    expect(lines).toContain('gateway');
    expect(lines).toContain('svc-a');
    expect(lines).toContain('svc-b');
    expect(lines).toContain('web');

    rmSync(dir, { recursive: true });
  }, CHILD_TEST_TIMEOUT);

  it('omits gateway when no entry', async () => {
    const dir = setupOrchestratorBundle({
      name: 'test',
      gateway: { name: 'gw', entry: '' },
      frontend: { name: 'web', dir: 'frontend' },
      services: { 'svc': { entry: 'services/svc/svc.cjs' } },
    });

    const result = await runOrchestrator(dir, ['--list']);
    const lines = result.stdout.trim().split('\n');
    expect(lines).not.toContain('gateway');
    expect(lines).toContain('svc');

    rmSync(dir, { recursive: true });
  }, CHILD_TEST_TIMEOUT);
});

describe('orchestrator --help', () => {
  it('prints usage and exits', async () => {
    const dir = setupOrchestratorBundle({
      name: 'test', gateway: { name: 'gw', entry: '' },
      frontend: { name: 'web', dir: 'frontend' }, services: {},
    });

    const result = await runOrchestrator(dir, ['--help']);
    expect(result.stdout).toContain('usage:');
    expect(result.stdout).toContain('--no-frontend');
    expect(result.code).toBe(0);

    rmSync(dir, { recursive: true });
  }, CHILD_TEST_TIMEOUT);
});

describe('orchestrator single-service mode', () => {
  it('runs a named service by requiring its entry', async () => {
    // this asserts the orchestrator resolves and requires the entry with PORT set.
    // it deliberately does NOT bind a socket: an entry that listens would make the
    // test depend on the sandbox allowing a real port bind and on the child living
    // long enough to be torn down, neither of which holds in a capsule container.
    const serviceCode = `
      console.log('SERVICE_STARTED:' + process.env.PORT);
      module.exports = {};
    `;
    const dir = setupOrchestratorBundle({
      name: 'test', gateway: { name: 'gw', entry: '' },
      frontend: { name: 'web', dir: 'frontend' },
      services: { 'my-svc': { entry: 'services/my-svc/my-svc.cjs' } },
    }, { 'services/my-svc/my-svc.cjs': serviceCode });

    // nothing binds, so the port is just a value to thread through and assert on.
    const result = await runOrchestrator(dir, ['my-svc'], { PORT: '9871' });
    expect(result.stdout).toContain('SERVICE_STARTED:9871');

    rmSync(dir, { recursive: true });
  }, CHILD_TEST_TIMEOUT);

  it('exits with error for unknown service', async () => {
    const dir = setupOrchestratorBundle({
      name: 'test', gateway: { name: 'gw', entry: '' },
      frontend: { name: 'web', dir: 'frontend' },
      services: { 'my-svc': { entry: 'services/my-svc/my-svc.cjs' } },
    });

    const result = await runOrchestrator(dir, ['nonexistent']);
    expect(result.stderr).toContain('unknown service');
    expect(result.stderr).toContain('my-svc');

    rmSync(dir, { recursive: true });
  }, CHILD_TEST_TIMEOUT);
});

/** reject `promise` if it has not settled in `ms`, so no await here is unbounded. */
function deadline<T>(promise: Promise<T>, ms: number, what: string): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`${what} did not settle in ${ms}ms`)), ms);
    promise.then(
      (v) => { clearTimeout(timer); resolve(v); },
      (e) => { clearTimeout(timer); reject(e); }
    );
  });
}

/**
 * always dial 127.0.0.1 rather than "localhost": on a dual-stack CI container
 * localhost can resolve to ::1 first and connect to nothing.
 */
function httpGet(port: number): Promise<string> {
  const http = require('http');
  return deadline(new Promise<string>((resolve, reject) => {
    const req = http.get({ host: '127.0.0.1', port, path: '/' }, (res: any) => {
      let data = '';
      res.on('data', (c: string) => data += c);
      res.on('end', () => resolve(data));
    });
    req.on('error', reject);
    req.setTimeout(2000, () => req.destroy(new Error('request timed out')));
  }), 3000, 'http get');
}

/** ask the OS for an unused port, so concurrent CI jobs never collide. */
function freePort(): Promise<number> {
  const net = require('net');
  return deadline(new Promise<number>((resolve, reject) => {
    const srv = net.createServer();
    srv.on('error', reject);
    srv.listen(0, '127.0.0.1', () => {
      const { port } = srv.address();
      srv.close(() => resolve(port));
    });
  }), 3000, 'free port lookup');
}

/** SIGTERM then SIGKILL, and wait for the exit: a surviving child keeps its stdio
 * pipes open, which is what makes vitest report "close timed out". */
function reap(child: any): Promise<void> {
  if (child.exitCode !== null || child.signalCode !== null) return Promise.resolve();
  return deadline(new Promise<void>((resolve) => {
    child.once('exit', () => resolve());
    child.kill('SIGTERM');
    setTimeout(() => child.kill('SIGKILL'), 1000);
  }), 3000, 'child reap').catch(() => undefined);
}

/**
 * resolve once the child announces it is listening, reject as soon as it dies.
 *
 * this must never outlast vitest's no-progress watchdog (BIT_VITEST_HANG_TIMEOUT,
 * 15s): a wait longer than the watchdog turns "the server didn't start" into an
 * aborted run with no diagnostics, instead of a failed assertion. so the ceiling
 * stays well under it and the child's own output is put in the error message.
 */
function waitForListening(child: any, needle: string, timeoutMs = 8000): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    let output = '';
    const done = (fn: () => void) => { clearTimeout(timer); fn(); };
    const timer = setTimeout(
      () => reject(new Error(`timed out after ${timeoutMs}ms waiting for "${needle}". child output:\n${output}`)),
      timeoutMs
    );
    const collect = (chunk: any) => {
      output += String(chunk);
      if (output.includes(needle)) done(resolve);
    };
    child.stdout?.on('data', collect);
    child.stderr?.on('data', collect);
    child.on('error', (err: Error) => done(() => reject(err)));
    child.on('exit', (code: number | null) =>
      done(() => reject(new Error(`child exited early (code ${code}). output:\n${output}`)))
    );
  });
}

describe('orchestrator frontend mode', () => {
  it('serves static frontend when run with "frontend" positional', async () => {
    const dir = setupOrchestratorBundle({
      name: 'test', gateway: { name: 'gw', entry: '' },
      frontend: { name: 'web', dir: 'frontend' },
      services: {},
    });
    const port = await freePort();

    const { execFile } = require('child_process');
    const child = execFile(process.execPath, [join(dir, 'backend.cjs'), 'frontend'], {
      env: { ...process.env, PORT: String(port) },
      timeout: 8000,
    });

    // the child must be reaped even when the assertion or the request fails,
    // otherwise it keeps the port and vitest cannot close its worker.
    try {
      await waitForListening(child, 'frontend serving at');
      const body = await httpGet(port);
      expect(body).toContain('<html>');
    } finally {
      await reap(child);
      rmSync(dir, { recursive: true });
    }
  }, CHILD_TEST_TIMEOUT);
});

describe('orchestrator env vars', () => {
  it('runModule passes services from *__PLATFORM_SERVICE_URL env vars', async () => {
    const serviceCode = `
      module.exports = { default: { run: function(ctx) {
        console.log('SERVICES:' + JSON.stringify(ctx.services));
        console.log('PORT:' + ctx.port);
        return Promise.resolve();
      }}};
    `;
    const dir = setupOrchestratorBundle({
      name: 'test', gateway: { name: 'gw', entry: '' },
      frontend: { name: 'web', dir: 'frontend' },
      services: { 'my-svc': { entry: 'services/my-svc/my-svc.cjs' } },
    }, { 'services/my-svc/my-svc.cjs': serviceCode });

    const result = await runOrchestrator(dir, ['my-svc'], {
      PORT: '4444',
      OTHER_SVC__PLATFORM_SERVICE_URL: 'http://other:5000',
      MONGO_URL: 'mongodb+srv://should-be-ignored',
      BACKEND_URL: 'http://gw:3000',
    });
    expect(result.stdout).toContain('PORT:4444');
    const servicesLine = result.stdout.split('\n').find((l: string) => l.startsWith('SERVICES:'));
    const services = JSON.parse(servicesLine!.replace('SERVICES:', ''));
    expect(services).toEqual([{ appName: 'other-svc', url: 'http://other:5000' }]);

    rmSync(dir, { recursive: true });
  }, CHILD_TEST_TIMEOUT);

  it('gateway warns when no *__PLATFORM_SERVICE_URL vars set', async () => {
    const gwCode = `module.exports = {};`;
    const dir = setupOrchestratorBundle({
      name: 'test',
      gateway: { name: 'gw', entry: 'gateway/gw.cjs' },
      frontend: { name: 'web', dir: 'frontend' },
      services: {},
    }, { 'gateway/gw.cjs': gwCode });

    const result = await runOrchestrator(dir, ['gateway']);
    const output = result.stdout + result.stderr;
    expect(output).toContain('warning');

    rmSync(dir, { recursive: true });
  }, CHILD_TEST_TIMEOUT);
});
